import{_ as e,c as o,o as d,a2 as i}from"./chunks/framework.BQGPkCej.js";const g=JSON.parse('{"title":"破坏性变更","description":"","frontmatter":{},"headers":[],"relativePath":"migration/guide/breaking_changes.md","filePath":"migration/guide/breaking_changes.md","lastUpdated":1720634491000}'),a={name:"migration/guide/breaking_changes.md"},c=i('<h1 id="破坏性变更" tabindex="-1">破坏性变更 <a class="header-anchor" href="#破坏性变更" aria-label="Permalink to &quot;破坏性变更&quot;">​</a></h1><p>本页面列出了 v3 相比以前的所有非兼容变更。</p><h2 id="项目环境" tabindex="-1">项目环境 <a class="header-anchor" href="#项目环境" aria-label="Permalink to &quot;项目环境&quot;">​</a></h2><ul><li><code>nodejs</code> 所需最低版本变为 <code>16+</code></li><li><a href="./../environment/index.html">项目包管理工具由 <code>npm</code> 变更为 <code>pnpm</code></a></li><li><a href="./../environment/redis.html"><code>redis</code> 所需最低部版本变更为 <code>v4+</code></a></li></ul><h2 id="核心库" tabindex="-1">核心库 <a class="header-anchor" href="#核心库" aria-label="Permalink to &quot;核心库&quot;">​</a></h2><ul><li><a href="./../core/index.html"><code>bot.client</code> 类进行了适配 <code>OneBot-11</code> 的重写</a></li><li><a href="./../core/config.html"><code>config</code> 工具类重构</a></li><li><a href="./../core/refresh.html"><code>refresh</code> 类从全局工具类中移除</a></li><li><code>file</code> 绝大多数方法改为异步，并同时提供了同步版本，例如 <code>loadYaml</code>（异步） 与 <code>loadYamlSync</code>（同步），建议尽可能地使用异步版本。</li><li><a href="./../../api/global/file.html#类型定义"><code>file</code> 部分方法返回值变更为 <code>FileTypeResponse</code> 与 <code>FileStatusResponse</code> 类型对象</a></li><li><a href="./../../guide/plugin/pic_render.html#常规注册方式"><code>renderer.register</code> 去除多余参数 <code>name</code> 与 <code>port</code></a></li><li><code>renderer</code> 工具类中 <code>renderer.asCqCode</code> 方法更名为 <code>renderer.asSegment</code>，调用方式不变</li><li>移除 <code>whiteList</code> 工具类，并将其合并至 <code>bot.config.whiteList</code>。</li></ul><h2 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h2><ul><li>不再内置 <code>genshin</code> 插件，需要自行前往插件库下载</li><li><a href="./../plugin/index.html">定义插件方式变更，由按需导出 <code>init</code> 命名函数改为默认导出<strong>对象</strong></a></li><li><a href="./../plugin/index.html">插件配置项 <code>fileName</code> 重命名为 <code>name</code></a></li><li><a href="./../core/refresh.html"><code>refresh</code> 注册方式变更，合并 <code>refresh.registerRefreshableFunc</code> 与 <code>refresh.registerRefreshableFile</code> 为 <code>refresh.register</code></a></li></ul><h2 id="指令" tabindex="-1">指令 <a class="header-anchor" href="#指令" aria-label="Permalink to &quot;指令&quot;">​</a></h2><ul><li><a href="./../directive/index.html">指令入口函数写法变更，由按需导出 <code>main</code> 命名函数改为默认导出<strong>匿名函数</strong></a></li><li><a href="./../directive/enquire.html"><code>Enquire</code> 类型指令重写</a></li></ul><h2 id="其他变化" tabindex="-1">其他变化 <a class="header-anchor" href="#其他变化" aria-label="Permalink to &quot;其他变化&quot;">​</a></h2><ul><li><a href="./../../guide/quick_start/web_console.html"><code>web-console</code> 的前端部分被抽离为一个独立的模块，需要预先执行一些操作来进行开发</a></li><li><code>node-fetch</code> 第三方包版本变化，如果你有手动定义返回值类型的需求，现在则需要手动从 <code>node-fetch</code> 中引入 <code>Response</code> 类型的返回值</li><li><code>redis</code> 类方法设置了更为严格的类型限制，参考<a href="./../../api/global/redis.html">工具类 Redis Api</a></li><li>所有路径别名追加 <code>\\</code>，避免语义不明明。即 <code>@modules</code> 变为 <code>@/modules</code>，<code>#genshin</code> 变为 <code>#/genshin</code>。</li></ul>',12),r=[c];function l(t,n,h,s,f,m){return d(),o("div",null,r)}const _=e(a,[["render",l]]);export{g as __pageData,_ as default};
